// Normalises the three entry points. The schedule always delivers. A manual
// run or a call from another workflow is a dry run unless it passes
// dry_run: false. Optional inputs: use_llm (default true) and date
// (YYYY-MM-DD, replaces today's Europe/Athens date for testing).
const input = $input.first()?.json ?? {};
const scheduled = Object.prototype.hasOwnProperty.call(input, 'timestamp')
  || Object.prototype.hasOwnProperty.call(input, 'Readable date');
const zone = 'Europe/Athens';
let now = DateTime.now().setZone(zone);
if (!scheduled && typeof input.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input.date)) {
  now = DateTime.fromISO(input.date, { zone }).set({ hour: now.hour, minute: now.minute, second: now.second });
}
return [{
  json: {
    job: "payments-unpaid",
    scheduled,
    dry_run: scheduled ? false : input.dry_run !== false,
    use_llm: scheduled ? true : input.use_llm !== false,
    now: now.toISO(),
    today: now.toISODate(),
    yesterday: now.minus({ days: 1 }).toISODate(),
    month_start: now.startOf('month').toISODate(),
    weekday: now.setLocale('en').toFormat('cccc'),
  },
}];

const MAX_MESSAGE = 3500;

function decodeEntities(text) {
  return String(text ?? '')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function oneLine(text, max) {
  let s = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (max && s.length > max) s = `${s.slice(0, max - 1).replace(/\s+\S*$/, '')}…`;
  return s;
}

// Link text must not break the Markdown link.
function linkText(text) {
  return oneLine(text, 160).replace(/\[/g, '(').replace(/\]/g, ')');
}

function errorText(error) {
  if (!error) return 'unknown error';
  if (typeof error === 'string') return oneLine(error, 200);
  return oneLine(error.message || error.description || JSON.stringify(error), 200);
}

// Joins a heading and bullet lines, dropping trailing bullets that would
// exceed the Talk message budget.
function buildMessage(head, lines, footer) {
  let out = head;
  let dropped = 0;
  for (const line of lines) {
    if (out.length + line.length + 1 + (footer ? footer.length + 2 : 0) > MAX_MESSAGE) {
      dropped += 1;
      continue;
    }
    out += `\n${line}`;
  }
  if (dropped) out += `\n- …and ${dropped} more`;
  if (footer) out += `\n\n${footer}`;
  return out;
}

// A bill is unpaid when it is active and has more pay dates on or before
// today (this month) than payments linked to it in the same range.
const opt = $('Run options').first().json;
const res = $input.first().json;
let data;
try { data = JSON.parse(res.data); } catch (e) { throw new Error(`Firefly bills: response is not JSON: ${oneLine(res.data, 120)}`); }
if (!Array.isArray(data?.data)) throw new Error(`Firefly bills: ${errorText(data?.message || 'no data array')}`);

const money = (value) => Number(value || 0).toFixed(2);
const rows = [];
for (const bill of data.data) {
  const a = bill.attributes || {};
  if (!a.active) continue;
  const due = (a.pay_dates || []).map((d) => String(d).slice(0, 10)).filter((d) => d <= opt.today).sort();
  const paid = (a.paid_dates || []).map((p) => String(p?.date || '').slice(0, 10)).filter(Boolean);
  for (const date of due.slice(paid.length)) {
    const amount = money(a.amount_min) === money(a.amount_max)
      ? money(a.amount_max)
      : `${money(a.amount_min)}–${money(a.amount_max)}`;
    rows.push({ date, line: `- **${linkText(a.name)}**: ${amount} ${a.currency_code || ''}, due ${date}`.replace(/ ,/, ',') });
  }
}
rows.sort((x, y) => x.date.localeCompare(y.date));
const message = rows.length ? buildMessage(`### Unpaid subscriptions, ${opt.today}\n`, rows.map((r) => r.line)) : '';
return [{ json: { message, deliver: Boolean(message) && !opt.dry_run, dry_run: opt.dry_run, items: rows.length, bills: data.data.length } }];

// Not delivered: a dry run, or nothing to report. Returned to a calling workflow.
const r = $input.first().json;
return [{ json: { ...r, delivered: false, reason: r.message ? 'dry run' : 'nothing to report' } }];

// This workflow is its own error workflow. Only failures of scheduled runs
// are posted; manual runs and dry runs show the error in n8n instead.
const e = $input.first().json;
const execution = e.execution || {};
const mode = String(execution.mode || '');
const node = execution.lastNodeExecuted || execution.error?.node?.name || 'unknown node';
const reason = String(execution.error?.message || execution.error?.description || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 300);
const message = `**${"payments-unpaid"} digest failed** (n8n, node "${node}"): ${reason}`;
return [{ json: { message, deliver: mode === 'trigger' || mode === 'webhook', mode } }];
